package main

import (
	"fmt"
	"reflect"
	"strconv"
	"strings"
)

// ValidationError represents a validation error.
type ValidationError struct {
	Field   string `json:"field"`
	Message string `json:"message"`
}

func (e ValidationError) Error() string {
	return fmt.Sprintf("validation error for field '%s': %s", e.Field, e.Message)
}

func validateArgs(args map[string]interface{}, schema map[string]interface{}) error {
	properties, ok := schema["properties"].(map[string]interface{})
	if !ok {
		return nil
	}

	required, _ := schema["required"].([]interface{})
	requiredFields := make(map[string]bool)
	for _, field := range required {
		if name, ok := field.(string); ok {
			requiredFields[name] = true
		}
	}

	for name := range requiredFields {
		if _, exists := args[name]; !exists {
			return ValidationError{Field: name, Message: "required field is missing"}
		}
	}

	for name, value := range args {
		propSchema, exists := properties[name].(map[string]interface{})
		if !exists {
			if additionalProps, ok := schema["additionalProperties"].(bool); ok && !additionalProps {
				return ValidationError{Field: name, Message: "field is not allowed"}
			}
			continue
		}
		if err := validateValue(name, value, propSchema); err != nil {
			return err
		}
	}
	return nil
}

func validateValue(name string, value interface{}, schema map[string]interface{}) error {
	expectedType, ok := schema["type"].(string)
	if !ok {
		return nil
	}

	if err := validateType(name, value, expectedType); err != nil {
		return err
	}
	if format, ok := schema["format"].(string); ok {
		if err := validateFormat(name, value, format); err != nil {
			return err
		}
	}
	if expectedType == "integer" || expectedType == "number" {
		if err := validateNumericConstraints(name, value, schema); err != nil {
			return err
		}
	}
	if expectedType == "string" {
		if err := validateStringConstraints(name, value, schema); err != nil {
			return err
		}
	}
	if enum, ok := schema["enum"].([]interface{}); ok {
		if err := validateEnum(name, value, enum); err != nil {
			return err
		}
	}
	return nil
}

func validateType(name string, value interface{}, expectedType string) error {
	actualType := getJSONType(value)
	if expectedType == "integer" && actualType == "number" {
		if num, ok := value.(float64); ok && num == float64(int64(num)) {
			return nil
		}
	}
	if actualType != expectedType {
		return ValidationError{Field: name, Message: fmt.Sprintf("expected type %s, got %s", expectedType, actualType)}
	}
	return nil
}

func validateFormat(name string, value interface{}, format string) error {
	s, ok := value.(string)
	if !ok {
		return nil
	}
	switch format {
	case "date-time":
		if !strings.Contains(s, "T") || !strings.Contains(s, ":") {
			return ValidationError{Field: name, Message: "invalid date-time format, expected RFC3339"}
		}
	case "date":
		if parts := strings.Split(s, "-"); len(parts) != 3 {
			return ValidationError{Field: name, Message: "invalid date format, expected YYYY-MM-DD"}
		}
	}
	return nil
}

func validateNumericConstraints(name string, value interface{}, schema map[string]interface{}) error {
	var num float64
	switch v := value.(type) {
	case int:
		num = float64(v)
	case int64:
		num = float64(v)
	case float64:
		num = v
	case string:
		var err error
		num, err = strconv.ParseFloat(v, 64)
		if err != nil {
			return ValidationError{Field: name, Message: "invalid numeric value"}
		}
	default:
		return ValidationError{Field: name, Message: "value is not numeric"}
	}

	if minVal, ok := schema["minimum"].(float64); ok && num < minVal {
		return ValidationError{Field: name, Message: fmt.Sprintf("value %g is less than minimum %g", num, minVal)}
	}
	if maxVal, ok := schema["maximum"].(float64); ok && num > maxVal {
		return ValidationError{Field: name, Message: fmt.Sprintf("value %g is greater than maximum %g", num, maxVal)}
	}
	return nil
}

func validateStringConstraints(name string, value interface{}, schema map[string]interface{}) error {
	s, ok := value.(string)
	if !ok {
		return nil
	}
	if maxLen, ok := schema["maxLength"].(float64); ok && len(s) > int(maxLen) {
		return ValidationError{Field: name, Message: fmt.Sprintf("string length %d exceeds maximum %d", len(s), int(maxLen))}
	}
	if minLen, ok := schema["minLength"].(float64); ok && len(s) < int(minLen) {
		return ValidationError{Field: name, Message: fmt.Sprintf("string length %d is less than minimum %d", len(s), int(minLen))}
	}
	if pattern, ok := schema["pattern"].(string); ok {
		switch pattern {
		case "^[A-Z]+$":
			for _, r := range s {
				if r < 'A' || r > 'Z' {
					return ValidationError{Field: name, Message: "value must contain only uppercase letters"}
				}
			}
		case "^[a-zA-Z0-9_]+$":
			for _, r := range s {
				if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_') {
					return ValidationError{Field: name, Message: "value must contain only letters, numbers, and underscores"}
				}
			}
		}
	}
	return nil
}

func validateEnum(name string, value interface{}, enum []interface{}) error {
	for _, e := range enum {
		if reflect.DeepEqual(value, e) {
			return nil
		}
	}
	return ValidationError{Field: name, Message: fmt.Sprintf("value must be one of: %v", enum)}
}

func getJSONType(value interface{}) string {
	switch value.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return "integer"
	case float32, float64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	default:
		return "unknown"
	}
}
